WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_conc_b_concentrate'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '蒸发浓缩', 'kp-conc-b-concentrate', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "蒸发浓缩问题"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心法则：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "溶质依然不变（盐跑不掉），只是溶液变少了。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "“一杯盐水放在太阳下晒，蒸发了 50克 水后，浓度由 10% 变成了 15%……”"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心破局"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "无论是加水还是蒸发水，这都是一个“溶质守恒方程”。"}]}, {"type": "katexBlock", "attrs": {"content": "\\text{初始溶液} \\times \\text{初始浓度} = (\\text{初始溶液} \\pm \\text{水}) \\times \\text{新浓度}"}}]}$$ AS jsonb), NULL, '蒸发浓缩的核心考点与实战推导。', category_node.id, CAST('["数量关系", "浓度问题", "蒸发浓缩"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_conc_b_concentrate", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
